package org.eclipse.rdf4j.common.webapp.system.logging;

import java.io.IOException;

import jakarta.servlet.Filter;
import jakarta.servlet.FilterChain;
import jakarta.servlet.ServletException;
import jakarta.servlet.ServletRequest;
import jakarta.servlet.ServletResponse;
import jakarta.servlet.http.HttpServletResponse;

/**
 * Deployment gate for the Server's diagnostic logging pages. Enabling the page does not authenticate its readers.
 */
public class LoggingAccessFilter implements Filter {

	private static final String ENABLED_PROPERTY = "org.eclipse.rdf4j.server.logging.ui.enabled";

	@Override
	public void doFilter(ServletRequest request, ServletResponse response, FilterChain chain)
			throws IOException, ServletException {
		if (!(response instanceof HttpServletResponse httpResponse)) {
			throw new ServletException("The logging access filter requires an HTTP response");
		}

		httpResponse.setHeader("Cache-Control", "no-store");
		if (!Boolean.getBoolean(ENABLED_PROPERTY)) {
			httpResponse.sendError(HttpServletResponse.SC_FORBIDDEN);
			return;
		}

		chain.doFilter(request, response);
	}
}
